"""Homepage composition. Uses the same verified content and shared site shell."""
from lxml import html as LH
import json

def ambient(kind):
    """Decorative vector contours: resolution independent, no video downloads."""
    return '<div class="ambient-layer ambient-'+kind+'" aria-hidden="true"><span class="ambient-orb orb-one"></span><span class="ambient-orb orb-two"></span><svg viewBox="0 0 1400 650" preserveAspectRatio="xMidYMid slice"><g class="contour-base">'+''.join('<path d="M -150 '+str(530+i*30)+' C 220 '+str(60+i*25)+', 550 '+str(850-i*48)+', 900 '+str(300+i*30)+' S 1290 '+str(-70+i*30)+', 1540 '+str(160+i*35)+'"/>' for i in range(5))+'</g><g class="contour-current">'+''.join('<path style="--delay:'+str(-i*4)+'s" d="M -150 '+str(530+i*30)+' C 220 '+str(60+i*25)+', 550 '+str(850-i*48)+', 900 '+str(300+i*30)+' S 1290 '+str(-70+i*30)+', 1540 '+str(160+i*35)+'"/>' for i in range(5))+'</g><g class="ambient-seed"><ellipse cx="1120" cy="200" rx="70" ry="110" transform="rotate(40 1120 200)"/><ellipse cx="1120" cy="200" rx="70" ry="110" transform="rotate(-40 1120 200)"/><circle cx="1120" cy="200" r="28"/></g></svg></div>'

def render_home(R,NEWS,icon,button,a,h):
    hero='''<section class="dynamic-hero" aria-label="Explore Business Management" aria-roledescription="carousel">
<div class="hero-photos"><img class="campus-slide active" src="assets/campus-main-building.webp" alt="Tzu Chi University main campus building" fetchpriority="high"><img class="campus-slide" src="assets/campus-mountain-building.webp" alt="Tzu Chi University campus with Hualien’s mountain landscape" aria-hidden="true"><img class="campus-slide" src="assets/photos/student-community.webp" alt="The department’s student community gathering" aria-hidden="true"></div><div class="campus-shade"></div>
<div class="wrap dynamic-hero-content"><div class="hero-title-block"><div class="hero-eyebrow"><span></span> TZU CHI UNIVERSITY · BUSINESS MANAGEMENT</div><h1 id="campus-title">Business<br><em>with purpose.</em></h1><p id="campus-description">Ideas that move business forward.<br>Values that bring people together.</p><div class="campus-actions">PRIMARY_ACTION<a class="campus-secondary" href="introduction.html">Discover our department <span>↗</span></a></div></div><a class="hero-memory" href="student-life.html"><img src="assets/photos/cafe-project.webp" alt="Students from the department’s Indonesian cohort presenting a project"><div><span>THIS IS LIFE AT BMD</span><b>Learn it.<br>Live it.</b><i aria-hidden="true">↗</i></div></a><div class="campus-location">HUALIEN, TAIWAN <span>LEARN · CONNECT · GROW</span></div></div>
<div class="hero-bottom-line"><div class="wrap hero-bottom-inner"><span class="hero-principles">HUMANITY <i></i> CREATIVITY <i></i> RESPONSIBILITY</span><div class="campus-controls"><button class="campus-pause" type="button" aria-label="Pause campus slideshow" aria-pressed="false">Ⅱ</button><div class="campus-dots" aria-label="Choose a campus slide"><button type="button" class="selected" aria-label="Show campus slide 1" aria-current="true">01</button><button type="button" aria-label="Show campus slide 2">02</button><button type="button" aria-label="Show campus slide 3">03</button></div><button class="campus-prev" type="button" aria-label="Previous campus slide">←</button><button class="campus-next" type="button" aria-label="Next campus slide">→</button></div></div></div><span class="sr-only" id="campus-announcement" aria-live="polite"></span></section>'''.replace('PRIMARY_ACTION',button('academics.html','Explore your possibilities','light'))
    quick=[('admissions.html','For future students','Your next chapter starts here.','✳'),('curriculum.html','For current students','Courses, credits, and resources.','↗'),('faculty.html','Meet our faculty','People behind your possibilities.','◎'),('internships.html','Step into practice','Internships, forms, and guidance.','⌁'),('exchange.html','Go beyond borders','Explore international experiences.','↗'),('outcomes.html','Ideas in action','Projects made by our students.','✧')]
    quick_html='<section class="wrap quick-launch" aria-label="Find department information" data-carousel><div class="quick-surface"><div class="quick-top"><span>MAKE YOUR NEXT MOVE</span><div class="track-controls"><button data-carousel-prev aria-label="Previous quick links">←</button><button data-carousel-next aria-label="Next quick links">→</button></div></div><div class="quick-track" data-carousel-track tabindex="0" aria-label="Quick links; scroll for more">'
    for i,(u,t,d,symbol) in enumerate(quick):quick_html+=f'<a class="quick-card" href="{u}"><span class="quick-symbol" aria-hidden="true">{symbol}</span><div><small>0{i+1}</small><h2>{t}</h2><p>{d}</p></div><span class="quick-arrow" aria-hidden="true">↗</span></a>'
    quick_html+='</div></div></section>'
    # The stream combines recent announcements with department achievements.
    achievements=[n for n in NEWS if n['category']=='achievements'][:3]
    selected=NEWS[:8]+achievements
    news='<section class="wrap home-stories" data-carousel data-home-news><div class="stories-heading"><div><div class="kicker">The BMD bulletin</div><h2>A lot is happening.<br><em>Find your next spark.</em></h2></div><div class="stories-heading-right">'+a('news.html','Visit the newsroom '+icon(),'text-link')+'<div class="track-controls"><button data-carousel-prev aria-label="Previous news cards">←</button><button data-carousel-next aria-label="Next news cards">→</button></div></div></div><div class="home-news-filters" aria-label="Filter homepage stories"><button class="active" data-home-news-filter="all" aria-pressed="true">All stories</button><button data-home-news-filter="announcements" aria-pressed="false">Announcements</button><button data-home-news-filter="achievements" aria-pressed="false">Student achievements</button></div><div class="stories-track" data-carousel-track tabindex="0" aria-label="Department news and achievements; scroll for more">'
    display_stories={
        '65682':('SustainSort: smarter waste sorting','Third place at TCU’s “Maker + Are You Ready?” proposal competition.'),
        '65256':('Turning waste into new possibilities','Second place in the Management Category at the 2025 National Business & Management Project Competition.'),
        '65248':('Exploring AI in education','Honorable mention for research on generative AI-assisted training question design.'),
    }
    for i,n in enumerate(selected):
        image=n['image']
        title,summary=next((copy for key,copy in display_stories.items() if key in n['url']),(n['title'],n['summary']))
        if '65682' in n['url']:image='assets/sustainsort-third-place.webp'
        visual='<img src="'+h(image)+'" alt="'+h(title)+'" loading="lazy">' if image else '<div class="story-placeholder" aria-hidden="true">BMD<br>Journal.</div>'
        news+='<article class="story-slide" data-news-type="'+n['category']+'"><a href="'+n['path']+'" class="story-image">'+visual+'<span class="story-open" aria-hidden="true">↗</span></a><div class="story-category"><span>'+h(n['label'])+'</span><i></i></div><h3>'+a(n['path'],h(title))+'</h3><p>'+h(summary[:180])+('…' if len(summary)>180 else '')+'</p></article>'
    news+='</div><div class="carousel-caption"><span>Good ideas travel. So do our students.</span><span class="carousel-count" aria-live="polite">SCROLL TO EXPLORE →</span></div></section>'
    life='''<section class="home-life"><div class="wrap life-layout"><div class="life-collage"><figure class="life-large"><img src="assets/photos/international-learning.webp" alt="Department students learning together" loading="lazy"><figcaption>Learning, out in the world.</figcaption></figure><figure class="life-small"><img src="assets/photos/design-workshop.webp" alt="Students taking part in a creative workshop" loading="lazy"><figcaption>MAKE SPACE FOR IDEAS.</figcaption></figure><span class="life-spark" aria-hidden="true">✳</span><span class="life-note">A little curiosity.<br>A world of possibilities.</span></div><div class="life-text"><div class="kicker">More than classroom learning</div><h2>The classroom<br>is just <em>the beginning.</em></h2><p>Run a student café. Develop a creative project. Learn with people from different cultures. Discover the experiences that turn knowledge into something real.</p><div class="life-routes"><a href="student-life.html"><span>Life at BMD</span><small>People, activities & shared experiences</small><b aria-hidden="true">↗</b></a><a href="exchange.html"><span>A wider world</span><small>Overseas learning & international exchange</small><b aria-hidden="true">↗</b></a></div></div></div></section>'''
    directions=[('01','Operations<br>Management','Understand operations and industries.','✳'),('02','Smart<br>Business','Connect digital tools with business insight.','↗'),('03','Sustainable<br>Innovation','Bring social responsibility into your ideas.','✧'),('04','Culinary<br>Management','Explore food, service, and applied management.','⌁')]
    paths='<section class="wrap home-pathways"><div class="pathways-heading"><div><div class="kicker">Explore the learning directions</div><h2>Find what<br><em>moves you.</em></h2></div><p>Build a foundation in business. Explore the department’s four distinctive directions and discover your next step.</p>'+a('curriculum.html','View the curriculum '+icon(),'text-link')+'</div><div class="pathways-grid">'
    for n,t,d,symbol in directions:paths+='<a class="pathway-card" href="academics.html"><span class="pathway-number">'+n+'</span><span class="pathway-symbol" aria-hidden="true">'+symbol+'</span><h3>'+t+'</h3><p>'+d+'</p><span class="pathway-arrow" aria-hidden="true">↗</span></a>'
    paths+='</div></section>'
    events=json.loads((R/'academic-events.json').read_text())['events']
    agenda='<section class="home-agenda"><div class="wrap"><div class="agenda-heading"><div><div class="kicker">Stay in the loop</div><h2>Make room<br>for <em>what’s next.</em></h2></div><div><p>Your academic calendar, right here.<br>Choose a date to see what’s scheduled.</p>'+a('assets/academic-calendar-2026-2027.pdf','Full academic calendar ↗','agenda-download',True)+'</div></div><div class="home-agenda-surface"><div class="home-agenda-list"><div class="agenda-list-header"><span>ON THE AGENDA</span><h3 id="event-list-title">October 2026</h3></div><div id="calendar-events" aria-live="polite"></div>'+a('events.html','View all academic dates '+icon(),'text-link')+'</div><div class="calendar" id="calendar"><div class="calendar-head"><button id="cal-previous" aria-label="Previous month">←</button><h3 id="calendar-month">October 2026</h3><button id="cal-next" aria-label="Next month">→</button></div><div class="weekdays">'+''.join('<span>'+d+'</span>' for d in ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'])+'</div><div class="days" id="calendar-days"></div><p class="calendar-hint">A green dot marks a listed event.<br>Select the date again to see the full month.</p></div></div><script type="application/json" id="calendar-data">'+json.dumps(events,ensure_ascii=False).replace('</','<'+chr(92)+'/')+'</script></div></section>'
    final='<section class="wrap home-final"><div><span class="kicker">Your next chapter</span><h2>A good place<br><em>to begin.</em></h2></div><div><p>Curious about studying Business Management?<br>Let’s find your next step.</p>'+button('admissions.html','Study with us')+'</div></section>'
    life=life.replace('<section class="home-life">','<section class="home-life motion-region">'+ambient('breeze'))
    life=life.replace('</div></div></div></section>','</div><button class="motion-toggle" type="button" aria-pressed="false" aria-label="Pause background animation"><span class="motion-state" aria-hidden="true">Ⅱ</span><span class="motion-label">Background motion on</span></button></div></div></section>')
    final=final.replace('<section class="wrap home-final">','<section class="home-final-shell motion-region">'+ambient('future')+'<div class="wrap home-final">').replace('</section>','</div></section>')
    return hero+quick_html+news+life+paths+agenda+final
